// Cloudflare entry point: the fetch handler generated by @opennextjs/cloudflare, plus a scheduled
// handler for the Cron Trigger in wrangler.jsonc (automatic job search).
// `.open-next/worker.js` is generated by `npm run cf:build`.
import nextWorker from "./.open-next/worker.js";

const worker = {
  fetch: nextWorker.fetch,

  /**
   * Runs at most one due automatic job search per tick by calling the app's scheduler route
   * in-process. The route authenticates the call with CRON_SECRET.
   */
  async scheduled(controller, env, ctx) {
    if (!env.CRON_SECRET) {
      console.log("[cron] CRON_SECRET is not set; automatic job search is off.");
      return;
    }
    const request = new Request("https://scheduler.internal/api/cron/job-search", {
      method: "POST",
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    const response = await nextWorker.fetch(request, env, ctx);
    console.log(`[cron ${controller.cron}] job search: ${response.status} ${await response.text()}`);
  },
};

export default worker;
